#include <fstream>
#include <stdexcept>
#include <cstring>
#include "study_cases.h"
#define CK(x) do{if((x)!=0)throw std::runtime_error(#x);}while(0)
const int G=16,R=10;const float FG=12345.5f,POISON=-23456.5f;const size_t IG=0xa5a55a5a;
template<class T>std::vector<T>readv(const char*n){std::ifstream f(n,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("fixtureopen");size_t sz=f.tellg();if(sz%sizeof(T))throw std::runtime_error("dtype");f.seekg(0);std::vector<T>v(sz/sizeof(T));if(!f.read((char*)v.data(),sz))throw std::runtime_error("shortfixture");return v;}
template<class T>T*upload(std::vector<T>v){T*p;CK(cudaMalloc(&p,v.size()*sizeof(T)));CK(cudaMemcpy(p,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));return p;}
template<class T>std::vector<T>get(T*p,int n){std::vector<T>v(n);CK(cudaMemcpy(v.data(),p,n*sizeof(T),cudaMemcpyDeviceToHost));return v;}
void append(std::vector<size_t>&out,std::vector<float>v){for(float x:v){unsigned bits;memcpy(&bits,&x,4);out.push_back(bits);}}
void append(std::vector<size_t>&out,std::vector<size_t>v){out.insert(out.end(),v.begin(),v.end());}
template<class T>std::vector<T>guard(std::vector<T>&v,int start,int n,T value){std::vector<T>a(n+32,value);std::copy(v.begin()+start,v.begin()+start+n,a.begin()+G);return a;}
struct State{Case c;std::vector<float>a,x,v,y;std::vector<size_t>rp,co,ro;float*da,*dx,*dv,*dy[3];size_t*drp,*dco,*dro;cusparseSpMatDescr_t mat[2];cusparseDnVecDescr_t vx,vy[2];void*buf[2];};
void capture(State&s,std::vector<size_t>&out){append(out,get(s.da,s.a.size()));append(out,get(s.dx,s.x.size()));append(out,get(s.dv,s.v.size()));append(out,get(s.drp,s.rp.size()));append(out,get(s.dco,s.co.size()));append(out,get(s.dro,s.ro.size()));for(auto p:s.dy)append(out,get(p,s.y.size()));}
int main(){static_assert(sizeof(size_t)==8,"64bit");auto f=readv<float>("input_f32.bin"),oracle=readv<float>("oracle_f32.bin");auto ix=readv<size_t>("indices_u64.bin");void*lib=dlopen("/usr/lib/x86_64-linux-gnu/libcusparse.so.12.0.1.140",RTLD_NOW|RTLD_LOCAL);if(!lib)throw std::runtime_error(dlerror());auto fn=(decltype(&cusparseSpMV))dlsym(lib,"cusparseSpMV");Dl_info info;if(!fn||!dladdr((void*)fn,&info))throw std::runtime_error("functionaddress");printf("STUDY_VENDOR SpMV=%s\n",info.dli_fname);cusparseHandle_t h;CK(cusparseCreate(&h));int version;CK(cusparseGetVersion(h,&version));cudaStream_t stream;cusparsePointerMode_t pm;CK(cusparseGetStream(h,&stream));CK(cusparseGetPointerMode(h,&pm));if(stream!=0||pm!=CUSPARSE_POINTER_MODE_HOST)throw std::runtime_error("policy");printf("STUDY_VENDOR version=%d stream=0 pointermode=0\n",version);float alpha=1,beta=0;std::vector<State>states;std::vector<size_t>prefix;
for(auto c:cases){State s;s.c=c;s.a=guard(f,c.ao,c.n*c.n,FG);s.x=guard(f,c.xo,c.n,FG);s.v=guard(f,c.vo,c.nnz,FG);s.rp=guard(ix,c.rpo,c.n+1,IG);s.co=guard(ix,c.co,c.nnz,IG);s.ro=guard(ix,c.ro,c.nnz,IG);s.y.assign(c.n+32,FG);std::fill(s.y.begin()+G,s.y.end()-G,POISON);s.da=upload(s.a);s.dx=upload(s.x);s.dv=upload(s.v);s.drp=upload(s.rp);s.dco=upload(s.co);s.dro=upload(s.ro);for(int k=0;k<3;k++)s.dy[k]=upload(s.y);CK(cusparseCreateCsr(&s.mat[0],c.n,c.n,c.nnz,s.drp+G,s.dco+G,s.dv+G,CUSPARSE_INDEX_64I,CUSPARSE_INDEX_64I,CUSPARSE_INDEX_BASE_ZERO,CUDA_R_32F));CK(cusparseCreateCoo(&s.mat[1],c.n,c.n,c.nnz,s.dro+G,s.dco+G,s.dv+G,CUSPARSE_INDEX_64I,CUSPARSE_INDEX_BASE_ZERO,CUDA_R_32F));CK(cusparseCreateDnVec(&s.vx,c.n,s.dx+G,CUDA_R_32F));for(int k=0;k<2;k++){CK(cusparseCreateDnVec(&s.vy[k],c.n,s.dy[k+1]+G,CUDA_R_32F));size_t bytes;CK(cusparseSpMV_bufferSize(h,CUSPARSE_OPERATION_NON_TRANSPOSE,&alpha,s.mat[k],s.vx,&beta,s.vy[k],CUDA_R_32F,CUSPARSE_SPMV_ALG_DEFAULT,&bytes));CK(cudaMalloc(&s.buf[k],std::max(bytes,size_t(1))));}capture(s,prefix);CK(cudaDeviceSynchronize());mv_dense<<<(c.n+255)/256,256>>>(c.n,s.da+G,s.dx+G,s.dy[0]+G);for(int k=0;k<2;k++)CK(fn(h,CUSPARSE_OPERATION_NON_TRANSPOSE,&alpha,s.mat[k],s.vx,&beta,s.vy[k],CUDA_R_32F,CUSPARSE_SPMV_ALG_DEFAULT,s.buf[k]));CK(cudaDeviceSynchronize());states.push_back(s);}
for(int trial=1;trial<=5;trial++){auto art=prefix;bool ok=true;double seconds=0;std::vector<double>components;
for(auto&s:states){auto c=s.c;for(int k=0;k<3;k++)CK(cudaMemcpy(s.dy[k],s.y.data(),s.y.size()*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());for(int k=0;k<3;k++){auto start=std::chrono::steady_clock::now();for(int r=0;r<R;r++){if(k==0)mv_dense<<<(c.n+255)/256,256>>>(c.n,s.da+G,s.dx+G,s.dy[0]+G);else CK(fn(h,CUSPARSE_OPERATION_NON_TRANSPOSE,&alpha,s.mat[k-1],s.vx,&beta,s.vy[k-1],CUDA_R_32F,CUSPARSE_SPMV_ALG_DEFAULT,s.buf[k-1]));}CK(cudaGetLastError());CK(cudaDeviceSynchronize());double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R;seconds+=t;components.push_back(t);}ok&=get(s.da,s.a.size())==s.a&&get(s.dx,s.x.size())==s.x&&get(s.dv,s.v.size())==s.v&&get(s.drp,s.rp.size())==s.rp&&get(s.dco,s.co.size())==s.co&&get(s.dro,s.ro.size())==s.ro;for(int k=0;k<3;k++){auto y=get(s.dy[k],s.y.size());for(int i=0;i<c.n+32;i++)ok&=y[i]==(i>=G&&i<c.n+G?oracle[c.oo+i-G]:FG);}capture(s,art);}
std::string path="spmv_trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)art.data(),art.size()*8);printf("STUDY_TRIAL {\"trial\":%d,\"correct\":%s,\"jit_excluded\":true,\"time_seconds\":%.12g,\"internal_repeats\":10,\"timing_region\":\"sum_five_cases_three_dense_CSR_COO_batches_completion_per_repeat\",\"max_abs_error\":0,\"max_rel_error\":0,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"shape\":[%zu],\"byte_order\":\"little\"}}\n",trial,ok?"true":"false",seconds,path.c_str(),art.size(),art.size());}
for(auto&s:states){for(int k=0;k<2;k++){CK(cusparseDestroySpMat(s.mat[k]));CK(cusparseDestroyDnVec(s.vy[k]));CK(cudaFree(s.buf[k]));}CK(cusparseDestroyDnVec(s.vx));for(auto p:{s.da,s.dx,s.dv,s.dy[0],s.dy[1],s.dy[2]})CK(cudaFree(p));for(auto p:{s.drp,s.dco,s.dro})CK(cudaFree(p));}CK(cusparseDestroy(h));}
